-- K-116 · MariaDB tuhaflığı: JSON_VALUE boş metin döndürünce REGEXP yanlış sonuç verir, CHECK içinde 'NULL argument passed'
-- hatası fırlatır (toplu e-posta şablonu kaydedilemiyordu). REGEXP'e giren JSON_VALUE açıkça utf8mb4 metne çevrilir.
-- Üretici (gen-schema.mts) artık böyle üretir; bu göç 0001 ile kurulmuş veritabanlarını düzeltir.
ALTER TABLE blog_categories DROP CONSTRAINT blog_categories_slug_format, ADD CONSTRAINT blog_categories_slug_format CHECK (((slug IS NULL) OR COALESCE(JSON_TYPE(slug) = 'OBJECT' AND JSON_LENGTH(slug) = JSON_CONTAINS_PATH(slug, 'one', '$.tr') + JSON_CONTAINS_PATH(slug, 'one', '$.en') AND COALESCE(CAST(JSON_VALUE(slug, '$.tr') AS CHAR CHARACTER SET utf8mb4) REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$' AND CHAR_LENGTH(CAST(JSON_VALUE(slug, '$.tr') AS CHAR CHARACTER SET utf8mb4)) <= 80 AND CAST(JSON_VALUE(slug, '$.tr') AS CHAR CHARACTER SET utf8mb4) NOT IN ('kategori','category','etiket','tag','arama','search','sayfa','page','403','api'), FALSE) AND (CAST(JSON_VALUE(slug, '$.en') AS CHAR CHARACTER SET utf8mb4) IS NULL OR COALESCE(CAST(JSON_VALUE(slug, '$.en') AS CHAR CHARACTER SET utf8mb4) REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$' AND CHAR_LENGTH(CAST(JSON_VALUE(slug, '$.en') AS CHAR CHARACTER SET utf8mb4)) <= 80 AND CAST(JSON_VALUE(slug, '$.en') AS CHAR CHARACTER SET utf8mb4) NOT IN ('kategori','category','etiket','tag','arama','search','sayfa','page','403','api'), FALSE)), FALSE)));
